        else message = '[INFO ] ' + message;

        // console.log('[ScanDownloader] ' + message);

        message = '\n[' + new Date().toLocaleTimeString() + '] ' + message;

        logContainer.textContent += message;
        if (!logContainerHovered) logContainer.scrollTop = logContainer.scrollHeight;
    }

    function parseComment(container) {
        return Array.from(container?.querySelectorAll('& > .wpd-comment') || [])
            .map((comment) => ({
                author: comment
                    .querySelector('& > .wpd-comment-wrap .wpd-comment-author')
                    ?.textContent?.trim(),
                date: comment
                    .querySelector('& > .wpd-comment-wrap .wpd-comment-date')
                    ?.textContent?.trim(),
                message: comment.querySelector('& > .wpd-comment-wrap .wpd-comment-text')
                    ?.textContent,
                replyTo: comment
                    .querySelector('& > .wpd-comment-wrap .wpd-reply-to')
                    ?.textContent?.replace(/\s{2}/g, ' '),
                replies: parseComment(comment)
            }))
            .filter((comment) => comment.author && comment.date && comment.message);
    }

    function getWidth(text, fontSize) {
        const canvas = document.createElement('canvas');
        const context = canvas.getContext('2d');
        context.font = `${fontSize}pt`;
        return context.measureText(text).width * 2;
    }

    function printComments(pdf, comments, level = 0) {
        comments.forEach((comment) => {
            /*
             *                          <- PDF_WIDTH ->
             * +------------------------------------------------------------------+
             * |                                                                  | /\ COMMENT_PADDING +
             * |  AUTHOR  DATE  REPLY_TO                                          | || max(AUTHOR_HEIGHT, DATE_HEIGHT, REPLY_TO_HEIGHT) +
             * |                                                                  | || COMMENT_GAP +
             * |  MESSAGE                                                         | || COMMENT_HEIGHT * lineCount +
             * |                                                                  | \/ COMMENT_PADDING
             * +------------------------------------------------------------------+
             */
            const message = comment.message.split('\n').flatMap((line) => {
                const lines = [];
                while (
                    getWidth(line, COMMENT_FONT_SIZE) >
                    PDF_WIDTH - 2 * COMMENT_PADDING - level * REPLY_PADDING
                ) {
                    const index = line.lastIndexOf(
                        ' ',
                        Math.floor(
                            (PDF_WIDTH - 2 * COMMENT_PADDING - level * REPLY_PADDING) /
                                (getWidth(line) / line.length)
                        )
                    );
                    lines.push(line.substring(0, index));
                    line = line.substring(index + 1);
                }
                lines.push(line);

                return lines;
            });
            const commentHeight =
                COMMENT_PADDING +
                Math.max(AUTHOR_HEIGHT, DATE_HEIGHT, REPLY_TO_HEIGHT) +
                COMMENT_GAP +
                (COMMENT_HEIGHT * message.length) / 2 +
                COMMENT_PADDING;

            pdf.addPage([PDF_WIDTH, commentHeight], PDF_WIDTH > commentHeight ? 'l' : 'p');
            pdf.setFillColor(COMMENT_BACKGROUND_COLOR);
            pdf.rect(0, 0, PDF_WIDTH, commentHeight, 'F');

            pdf.setFontSize(AUTHOR_FONT_SIZE);
            pdf.setTextColor(AUTHOR_COLOR);
            pdf.text(
                comment.author,
                COMMENT_PADDING + level * REPLY_PADDING,
                COMMENT_PADDING + Math.max(AUTHOR_HEIGHT, DATE_HEIGHT, REPLY_TO_HEIGHT) / 2
            );

            pdf.setFontSize(DATE_FONT_SIZE);
            pdf.setTextColor(DATE_COLOR);
            pdf.text(
                comment.date,
                COMMENT_PADDING +
                    getWidth(comment.author, AUTHOR_FONT_SIZE) +
                    COMMENT_GAP +
                    level * REPLY_PADDING,
                COMMENT_PADDING + Math.max(AUTHOR_HEIGHT, DATE_HEIGHT, REPLY_TO_HEIGHT) / 2
            );

            if (comment.replyTo) {
                pdf.setFontSize(REPLY_TO_FONT_SIZE);
                pdf.setTextColor(REPLY_TO_COLOR);
                pdf.text(
                    comment.replyTo,
                    COMMENT_PADDING +
                        getWidth(comment.author, AUTHOR_FONT_SIZE) +
                        COMMENT_GAP +
                        getWidth(comment.date, DATE_FONT_SIZE) +
                        level * REPLY_PADDING,
                    COMMENT_PADDING + Math.max(AUTHOR_HEIGHT, DATE_HEIGHT, REPLY_TO_HEIGHT) / 2
                );
            }

            pdf.setFontSize(COMMENT_FONT_SIZE);
            pdf.setTextColor(COMMENT_COLOR);
            message.forEach((line, index) => {
                pdf.text(
                    line,
                    COMMENT_PADDING + level * REPLY_PADDING,
                    COMMENT_PADDING +
                        Math.max(AUTHOR_HEIGHT, DATE_HEIGHT, REPLY_TO_HEIGHT) +
                        COMMENT_GAP +
                        (COMMENT_HEIGHT * index) / 2
                );
            });

            printComments(pdf, comment.replies, level + 1);
        });
    }

    async function downloadScans() {
        const start = Date.now();
        let infos = '';
        let totalSize = 0;
        let totalPdfSize = 0;
        let hasError = false;

        const directory = await window.showDirectoryPicker();
        if (!directory) {
            throw new Error('User cancelled download');
        }

        // Used to keep the directory handle alive and prevent the browser from
        // emitting a permission error when trying to write to the directory
        await directory.getFileHandle(`tmp.txt`, {
            create: true
        });
        directory.removeEntry('tmp.txt');

        if (!window.jsPDF) {
            const pdfScript = document.createElement('script');
            pdfScript.src = 'https://cdn.jsdelivr.net/npm/jspdf@2.5.2/dist/jspdf.umd.min.js';
            document.head.appendChild(pdfScript);
            pdfScript.onerror = (error) => console.error('Failed to load PDF library:', error);
            await new Promise((resolve) => (pdfScript.onload = resolve));
        }

        try {
            log('Listing chapters...');
            const chapters = Array.from(document.querySelectorAll('.wp-manga-chapter > a'))
                .map((a) => ({ name: a.textContent.trim(), url: a.href }))
                .reverse();

            log('Listing already downloaded chapters...');
            const downloadedChapters = {};
            for await (const entry of directory.values()) {
                if (entry.kind === 'file' && entry.name.endsWith('.pdf')) {
                    downloadedChapters[entry.name.replace('.pdf', '')] = true;
                }
            }

            log('Filtering chapters...');
            const chaptersToDownload = chapters.filter(
                (chapter) => !downloadedChapters[chapter.name]
            );
            infos += `SETTINGS :\n    PARALLEL_OPERATION_COUNT : ${PARALLEL_OPERATION_COUNT}\n    MAX_LOG_LENGTH : ${MAX_LOG_LENGTH}\n    MAX_PDF_HEIGHT : ${MAX_PDF_HEIGHT}\n    PDF_WIDTH : ${PDF_WIDTH}\n\n`;
            infos += `\nINITIAL SCAN INFOS :\n    TOTAL CHAPTERS : ${
                chapters.length
            }\n    DOWNLOADED CHAPTERS : ${
                Object.keys(downloadedChapters).length
            }\n    CHAPTERS TO DOWNLOAD : ${chaptersToDownload.length}\n\n`;
            infos += `\nCHAPTERS TO DOWNLOAD :\n`;
            chaptersToDownload.forEach((chapter, index) => {
                infos += `    ${index + 1} - ${chapter.name} : ${chapter.url}\n`;
            });

            if (chaptersToDownload.length === 0) {
                log('No new chapters to download!');
                return;
            }

            hasError = false;
            let last = -1;
            await Promise.all(
                Array.from({ length: PARALLEL_OPERATION_COUNT }, async () => {
                    while (last < chaptersToDownload.length - 1) {
                        const current = ++last;
                        log(`Processing ${current + 1}/${chaptersToDownload.length}...`);

                        const response = await fetch(
                            chaptersToDownload[current].url + '?style=list'
                        );
                        const text = await response.text();
                        const doc = new DOMParser().parseFromString(text, 'text/html');
                        const images = Array.from(doc.querySelectorAll('.page-break > img')).map(
                            (img) => img.src
                        );
                        chaptersToDownload[current].images = images;

                        // Comments
                        const commentsContainer = doc.querySelector(
                            '#wpd-threads > .wpd-thread-list'
                        );
                        chaptersToDownload[current].comments = parseComment(commentsContainer);
                    }
                })
            );

            infos += `\nCHAPTERS INFOS :\n`;
            chaptersToDownload.forEach((chapter, index) => {
                infos += `    ${index + 1} - ${chapter.name} : ${chapter.images.length} pages\n`;
            });

            infos += `\nDOWNLOADED CHAPTERS INFOS :\n`;

            hasError = false;
            last = -1;
            await Promise.all(
                Array.from({ length: PARALLEL_OPERATION_COUNT }, async () => {
                    while (last < chaptersToDownload.length - 1 && !hasError) {
                        const current = ++last;
                        const start = Date.now();
                        let size = 0;
                        log(
                            `Downloading chapter "${chaptersToDownload[current].name}" (${
                                current + 1
                            }/${chaptersToDownload.length}) (${
                                chaptersToDownload[current].images.length
                            } pages)...`
                        );

                        const pdf = new jspdf.jsPDF({ compress: true });
                        pdf.deletePage(1);
                        for (let j = 0; j < chaptersToDownload[current].images.length; j++) {
                            if (hasError) break;
                            log(
                                `Downloading page ${j + 1}/${
                                    chaptersToDownload[current].images.length
                                } of chapter "${chaptersToDownload[current].name}" (${
                                    current + 1
                                }/${chaptersToDownload.length})...`
                            );
                            const response = await fetch(chaptersToDownload[current].images[j]);
                            const blob = await response.blob();
                            const url = URL.createObjectURL(blob);
                            const img = new Image();
                            img.src = url;

                            try {
                                await new Promise((resolve, reject) => {
                                    img.onload = resolve;
                                    img.onerror = reject;
                                });
                            } catch {
                                pdf.addPage(
                                    [PDF_WIDTH, IMAGE_LOADING_ERROR_HEIGHT],
                                    PDF_WIDTH > IMAGE_LOADING_ERROR_HEIGHT ? 'l' : 'p'
                                );
                                pdf.setFillColor(IMAGE_LOADING_ERROR_BACKGROUND_COLOR);
                                pdf.rect(0, 0, PDF_WIDTH, IMAGE_LOADING_ERROR_HEIGHT, 'F');
                                pdf.setTextColor(IMAGE_LOADING_ERROR_COLOR);
                                pdf.setFontSize(IMAGE_LOADING_ERROR_FONT_SIZE);
                                pdf.text(
                                    IMAGE_LOADING_ERROR_TEXT,
                                    PDF_WIDTH / 2,
                                    IMAGE_LOADING_ERROR_HEIGHT / 2,
                                    { align: 'center', baseline: 'middle' }
                                );
                                URL.revokeObjectURL(url);
                                continue;
                            }

                            const height = PDF_WIDTH * (img.height / img.width);
                            size += blob.size;

                            if (height > MAX_PDF_HEIGHT) {
                                let y = 0;
                                while (y < height) {
                                    const pageHeight = Math.min(MAX_PDF_HEIGHT, height - y);
                                    pdf.addPage(
                                        [PDF_WIDTH, pageHeight],
                                        PDF_WIDTH > pageHeight ? 'l' : 'p'
                                    );
                                    pdf.addImage(img, 'JPEG', 0, -y, PDF_WIDTH, height);
                                    y += MAX_PDF_HEIGHT;
                                }
                            } else {
                                pdf.addPage([PDF_WIDTH, height], PDF_WIDTH > height ? 'l' : 'p');
                                pdf.addImage(img, 'JPEG', 0, 0, PDF_WIDTH, height);
                            }
                            URL.revokeObjectURL(url);
                        }

                        // Comments
                        if (chaptersToDownload[current].comments.length > 0) {
                            pdf.setFontSize(TITLE_FONT_SIZE);
                            pdf.setFillColor(TITLE_BACKGROUND_COLOR);
                            pdf.rect(0, 0, PDF_WIDTH, TITLE_HEIGHT, 'F');
                            pdf.setTextColor(TITLE_COLOR);
                            pdf.addPage(
                                [PDF_WIDTH, TITLE_HEIGHT],
                                PDF_WIDTH > TITLE_HEIGHT ? 'l' : 'p'
                            );
                            pdf.text('Comments', PDF_WIDTH / 2, TITLE_HEIGHT / 2, {
                                align: 'center',
                                baseline: 'middle'
                            });
                            printComments(pdf, chaptersToDownload[current].comments);
                        }

                        if (hasError) break;
                        const file = await directory.getFileHandle(
                            `${chaptersToDownload[current].name}.pdf`,
                            {
                                create: true
                            }
                        );
                        const writable = await file.createWritable();
                        const blob = pdf.output('blob');
                        await writable.write(blob);
                        await writable.close();

                        const end = Date.now();

                        log(
                            `Chapter "${chaptersToDownload[current].name}" (${current + 1}/${
                                chaptersToDownload.length
                            }) downloaded !`
                        );
                        infos += `    ${current + 1} - ${
                            chaptersToDownload[current].name
                        } : ${formatSize(size)} (${
                            chaptersToDownload[current].images.length
                        } pages) => ${formatSize(
                            blob.size
                        )} (${pdf.internal.getNumberOfPages()} pages), ${formatDuration(
                            end - start
                        )}, ${formatSize((blob.size / (end - start)) * 1000)}/s\n`;
                        totalSize += size;
                        totalPdfSize += blob.size;
                    }
                })
            );

            log('Download complete! Took ' + formatDuration(Date.now() - start));
        } catch (error) {
            hasError = true;
            log(error);
            console.error('[ScanDownloader]', error);

            infos += `\nERROR : ${error.message}\n`;
        }

        const end = Date.now();
        infos += `\nFINAL SCAN INFOS :\n    TOOK : ${formatDuration(
            end - start
        )}\n    TOTAL SIZE : ${formatSize(totalSize)}\n    TOTAL PDF SIZE : ${formatSize(
            totalPdfSize
        )}\n    AVERAGE SPEED : ${formatSize((totalPdfSize / (end - start)) * 1000)}/s\n`;

        console.log('[ScanDownloader]', infos);

        const file = await directory.getFileHandle(
            `infos-${new Date().toJSON().replace(/:/g, '-').replace(/\..+/, '')}.txt`,
            {
                create: true
            }
        );
        const writable = await file.createWritable();
        await writable.write(infos);
        await writable.close();
    }

    if (!document.getElementById('download-all-scans')) {
        const downloadButton = document.createElement('a');
        downloadButton.textContent = 'Download all scans';
        downloadButton.href = '#';
        downloadButton.className = 'c-btn c-btn_style-1';
        downloadButton.id = 'download-all-scans';
        downloadButton.addEventListener('click', (event) => {
            event.preventDefault();
            downloadButton.remove();
            logContainer.style.display = 'block';
            downloadScans();
        });

        const buttonsContainer = document.getElementById('init-links');
        buttonsContainer.appendChild(downloadButton);
    }
})();

